import math
def priority(task, state, m=2.0, k=1.0, guard=2.0, hard=1e4, type_map=1.0, type_reduce=1.0, type_join=1.0):
    # Late-tier gating plus task_type-aware base weighting, since different
    # stage types may have different sensitivity to queueing delay.
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        tw = type_map
    elif task.task_type == 'reduce':
        tw = type_reduce
    elif task.task_type == 'join':
        tw = type_join
    else:
        tw = 1.0
    base = tier * tw * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    wait = state.now - task.release
    ratio = wait / est
    late = 1.0 if ratio >= guard else 0.0
    return late * hard + base  # tuned (m=0.904,k=0.312,guard=0.831,hard=2.85e+04,type_map=0.635,type_reduce=3.43,type_join=0.693)

def priority(task, state, b=0.5, c=1.0, qthresh=10.0, guard=1e6):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    base = task.weight / est * (1 + b * ratio)
    if ratio >= c:
        return guard + base
    if state.queue_len >= qthresh:
        return base * (1.0 + ratio)
    return base  # tuned (b=0.981,c=1.22,qthresh=3.55,guard=3.43e+05)

def priority(task, state, b=2.0, c=2.0, boost=1e6, wtype=1.0):
    wait = state.now - task.release
    est = max(task.estimated_runtime, 1e-6)
    ratio = wait / est
    tier = 2.0 if task.tenant == 'premium' else 1.0
    type_mult = wtype if task.task_type == 'reduce' else 1.0
    base = tier * type_mult * task.weight / est * (1 + b * ratio)
    if ratio >= c:
        return boost + base
    return base  # tuned (b=7.8,c=0.691,boost=3.65e+06,wtype=0.702)
